diff --git a/core/render/sdf/framework.h b/core/render/sdf/framework.h
index 7108e4056..a1a7b84c7 100644
--- a/core/render/sdf/framework.h
+++ b/core/render/sdf/framework.h
@@ -479,12 +479,9 @@ struct OctetEvents : FrameworkPlaneStreams<4> {
     inverse_spacing = 1.0f / spacing;
     wire_radius = geometry.wire_radius;
     const math::Vector ORIGIN = ray.origin - geometry.origin;
-    std::array<FrameworkPlaneCursor::Projection, STREAM_COUNT> projections;
     for (size_t i = 0; i < STREAM_COUNT; ++i) {
       positions[i] = math::dot(ORIGIN, FAMILIES[i].normal);
       speeds[i] = math::dot(ray.direction, FAMILIES[i].normal);
-      projections[i] = {positions[i] + ray.interval.near * speeds[i], speeds[i],
-                        spacing};
     }
     size_t pair = 0;
     std::array<bool, STREAM_COUNT> owned{};
@@ -501,12 +498,19 @@ struct OctetEvents : FrameworkPlaneStreams<4> {
                        OWNER, OWNER == i ? j : i};
         owned[OWNER] = true;
       }
-    FrameworkPlaneCursor::initialize(cursors.data(), projections.data(),
-                                     STREAM_COUNT, ray.interval.near);
     for (size_t i = 0; i < STREAM_COUNT; ++i) {
-      cursors[i].active = cursors[i].active && owned[i];
       positions[i] *= inverse_spacing;
       speeds[i] *= inverse_spacing;
+      if (!owned[i])
+        continue;
+      const float CELL = positions[i] + ray.interval.near * speeds[i];
+      const float PLANE = speeds[i] > 0.0f ? ceilf(CELL) : floorf(CELL);
+      const float INVERSE_SPEED = 1.0f / speeds[i];
+      auto &cursor = cursors[i];
+      cursor.next = ray.interval.near + (PLANE - CELL) * INVERSE_SPEED;
+      cursor.step = fabsf(INVERSE_SPEED);
+      cursor.active = Raycast::finite(cursor.next) &&
+                      Raycast::finite(cursor.step) && cursor.step > 0.0f;
     }
     for (auto &pair : pairs)
       pair.scale *= spacing * spacing;
